    {
        $mod10 = $n % 10;
        $mod100 = $n % 100;
        if ($mod10 === 1 && $mod100 !== 11 && $mod100 !== 71 && $mod100 !== 91) {
            return PluralCategory::One;
        }
        if ($mod10 === 2 && $mod100 !== 12 && $mod100 !== 72 && $mod100 !== 92) {
            return PluralCategory::Two;
