        if (($mod10 === 3 || $mod10 === 4 || $mod10 === 9) && !($mod100 >= 10 && $mod100 <= 19) && !($mod100 >= 70 && $mod100 <= 79) && !($mod100 >= 90 && $mod100 <= 99)) {
            return PluralCategory::Few;
        }
        if ($n !== 0 && $n % 1000000 === 0) {
            return PluralCategory::Many;
        }

        return PluralCategory::Other;
    }

